use std::sync::Arc;

use commands::AppState;
use service::SnippetService;
use storage::Repository;
use tauri::Manager;

pub fn run() {
    tauri::Builder::default()
        .setup(|app| {
            let data_dir = app
                .path()
                .app_data_dir()
                .map_err(|error| error.to_string())?;
            let state = match Repository::open(&data_dir) {
                Ok(repository) => AppState {
                    service: Some(Arc::new(SnippetService::new(repository))),
                    startup_error: None,
                },
                Err(error) => {
                    eprintln!("Searchis database startup failed: {}", error.code);
                    AppState {
                        service: None,
                        startup_error: Some(error),
                    }
                }
            };
            eprintln!(
                "Searchis environment: os={} arch={} desktop={} session={}",
                std::env::consts::OS,
                std::env::consts::ARCH,
                std::env::var("XDG_CURRENT_DESKTOP").unwrap_or_else(|_| "unknown".into()),
                std::env::var("XDG_SESSION_TYPE").unwrap_or_else(|_| "unknown".into()),
            );
            app.manage(state);
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            commands::snippet_create,
            commands::snippet_get,
            commands::snippet_list,
            commands::snippet_update,
        ])
        .run(tauri::generate_context!())
        .expect("Searchis Tauri runtime failed");
}

