368	fn read_key(path: &Path) -> Result<Vec<u8>, AppError> {
369	    let metadata = fs::symlink_metadata(path)
370	        .map_err(|_| key_error("无法检查数据库密钥文件。请修复文件权限。"))?;
371	    if metadata.file_type().is_symlink() || !metadata.is_file() {
372	        return Err(key_error("数据库密钥必须是普通文件，不能是符号链接。"));
373	    }
374	    if metadata.permissions().mode() & 0o777 != 0o600
375	        || metadata.uid() != unsafe { libc::geteuid() }
376	    {
377	        return Err(key_error(
378	            "数据库密钥权限或所有者不安全。请将所有者改为当前用户并执行 chmod 600 database.key。",
379	        ));
380	    }
381	    let mut bytes = Vec::with_capacity(KEY_BYTES);
382	    OpenOptions::new()
383	        .read(true)
384	        .open(path)
385	        .and_then(|mut file| file.read_to_end(&mut bytes))
386	        .map_err(|_| key_error("无法读取数据库密钥。请检查文件权限或恢复密钥。"))?;
387	    if bytes.len() != KEY_BYTES {
388	        return Err(key_error("数据库密钥长度无效。请恢复原始 database.key。"));
389	    }
390	    Ok(bytes)
391	}
392	
393	fn create_key(path: &Path) -> Result<Vec<u8>, AppError> {
394	    let mut key = vec![0u8; KEY_BYTES];
395	    rand::rngs::OsRng
396	        .try_fill_bytes(&mut key)
397	        .map_err(|_| key_error("系统随机数生成失败，未创建数据库。请检查操作系统后重试。"))?;
398	    let mut file = OpenOptions::new()
399	        .write(true)
400	        .create_new(true)
401	        .mode(0o600)
402	        .open(path)
403	        .map_err(|_| key_error("无法原子创建数据库密钥。请检查数据目录中是否已有异常文件。"))?;
404	    if file.write_all(&key).and_then(|_| file.sync_all()).is_err() {
405	        drop(file);
406	        let _ = fs::remove_file(path);
407	        return Err(key_error(
408	            "数据库密钥写入失败且已清理不完整文件。请检查磁盘空间后重试。",
409	        ));
410	    }
410	    }
411	    drop(file);
412	    read_key(path)
413	}
