393	fn create_key(path: &Path) -> Result<Vec<u8>, AppError> {
394	    let mut key = vec![0u8; KEY_BYTES];
395	    rand::rngs::OsRng
396	        .try_fill_bytes(&mut key)
397	        .map_err(|_| key_error("系统随机数生成失败，未创建数据库。请检查操作系统后重试。"))?;
398	    let mut file = OpenOptions::new()
399	        .write(true)
400	        .create_new(true)
401	        .mode(0o600)
402	        .open(path)
403	        .map_err(|_| key_error("无法原子创建数据库密钥。请检查数据目录中是否已有异常文件。"))?;
404	    if file.write_all(&key).and_then(|_| file.sync_all()).is_err() {
405	        drop(file);
406	        let _ = fs::remove_file(path);
407	        return Err(key_error(
408	            "数据库密钥写入失败且已清理不完整文件。请检查磁盘空间后重试。",
409	        ));
410	    }
410	    }
411	    drop(file);
412	    read_key(path)
413	}
